 readonly Dictionary<CancellationTokenSource,string> frozenReaderIds=new Dictionary<CancellationTokenSource,string>();
 readonly List<CancellationTokenSource> frozenReaders=new List<CancellationTokenSource>();
 internal static bool FrozenConfigurationAction(string action){return new[]{"frozenConfigurationRead","frozenConfigurationSources","frozenConfigurationSave","frozenConfigurationApprove","frozenConfigurationUninstall","frozenConfigurationRecover","frozenConfigurationCancel","frozenConfigurationReadCancel"}.Contains(action);}
 static string[] FrozenIds(object value,bool tokens=false){var items=value as IEnumerable;if(value is string||value is IDictionary||items==null)throw new IOException("快照清单必须是数组。");var values=items.Cast<object>().ToArray();if(values.Length>2000||values.Any(v=>!(v is string)))throw new IOException("快照清单格式无效。");var result=values.Cast<string>().ToArray();if(result.Distinct(StringComparer.Ordinal).Count()!=result.Length||tokens&&result.Any(v=>!Regex.IsMatch(v,@"\A[a-f0-9]{64}\z")))throw new IOException("快照来源标识无效或重复。");return tokens?result:ModConfigurations.ValidatePreflightMods(result);}
 internal static void ValidateFrozenConfigurationPayload(string action,Dictionary<string,object> p){
  if(!FrozenConfigurationAction(action))return;var keys=action=="frozenConfigurationReadCancel"?new[]{"snapshotId","readId"}:action=="frozenConfigurationRead"||action=="frozenConfigurationCancel"?new[]{"snapshotId"}:(action=="frozenConfigurationSources"||action=="frozenConfigurationRecover")?new[]{"snapshotId","manifestHash"}:action=="frozenConfigurationUninstall"?new[]{"snapshotId","manifestHash","componentIds"}:action=="frozenConfigurationApprove"?new[]{"snapshotId","manifestHash","approvalToken","decision"}:new[]{"snapshotId","manifestHash","ordinaryIds","componentIds","sourceTokens"};
  if(action=="frozenConfigurationSources"&&p!=null&&p.ContainsKey("readId"))keys=keys.Concat(new[]{"readId"}).ToArray();
  if(p!=null&&p.ContainsKey("readId")&&(!(p["readId"] is string)||!Regex.IsMatch((string)p["readId"],@"\A[a-f0-9]{32}\z")))throw new IOException("快照读取标识无效。");
  if(p==null||p.Count!=keys.Length||keys.Any(k=>!p.ContainsKey(k))||!(p["snapshotId"] is string)||!Regex.IsMatch((string)p["snapshotId"],@"\A[a-f0-9]{32}\z"))throw new IOException("快照操作只接受本机登记标识。");
  foreach(string k in new[]{"manifestHash","approvalToken"})if(p.ContainsKey(k)&&(!(p[k] is string)||!Regex.IsMatch((string)p[k],@"\A[a-f0-9]{64}\z")))throw new IOException("快照版本或来源凭据无效。");if(p.ContainsKey("decision")&&!(p["decision"] is bool))throw new IOException("请明确允许或拒绝此文件。");foreach(string k in new[]{"ordinaryIds","componentIds","sourceTokens"})if(p.ContainsKey(k))FrozenIds(p[k],k=="sourceTokens");
 }
 ModernController FrozenTarget(string action,Dictionary<string,object> payload){ValidateFrozenConfigurationPayload(action,payload);return BoundConfigurationController(ConfigurationProfiles().Resolve("snapshot:"+Text(payload,"snapshotId")));}
 object FrozenView(SaveEnvironmentRecord row){var warnings=new List<string>();var copiedEngine=new Engine(row.GamePath,row.UserPath,engine.Data,engine.TestMode,engine.ReadSteamOptions,engine.ProcessInventory,false){FrozenEnvironment=row};var catalog=SaveProfiles.SnapshotEntries(copiedEngine,row.ModRoots.SelectMany(r=>r.ModIds).Distinct().ToArray(),warnings,new LaunchReadBudget(67108864,100000));var components=FrozenConfigurationEditor.Components(row);return new{snapshotId=row.Id,name=row.Name,manifestHash=row.ManifestHash,gameVersion=row.GameVersion,ordinaryIds=row.DefaultModIds.Except(components).ToArray(),componentIds=components,managedIds=FrozenConfigurationEditor.Managed(row),copied=row.ModRoots.SelectMany(r=>r.ModIds.Select(id=>{var entry=catalog.Entries.FirstOrDefault(e=>e.id==id);return new{id,name=entry==null?id:entry.name,workshopId=r.WorkshopId,requires=entry==null?new string[0]:entry.requires,loadAfter=entry==null?new string[0]:entry.loadAfter,loadBefore=entry==null?new string[0]:entry.loadBefore,map=entry!=null&&entry.map,component=(FrozenConfigurationEditor.Managed(row)).Contains(id),java=(row.JavaRules??new FrozenJavaRule[0]).Any(rule=>rule.ModId==id)};})).ToArray(),java=(row.JavaRules??new FrozenJavaRule[0]).Select(r=>new{id=r.ModId,sha256=r.Hash,approvalToken=FrozenJavaPolicy.Token(r),decision=r.Approved,enabled=r.Allowed}).ToArray(),warnings=row.CleanupWarnings.Concat(warnings).ToArray()};}
