 SaveEnvironmentRecord CurrentFrozen(Dictionary<string,object> p,bool readOnly=false){var registration=readOnly?SaveEnvironments.RegisteredForUsers(engine.Data,new[]{engine.User}).SingleOrDefault(item=>item.Id==Text(p,"snapshotId")):null;var row=readOnly?registration==null?null:registration.Record:SaveEnvironments.FindOwned(engine.Data,engine.Game,engine.User);if(row==null||row.Id!=Text(p,"snapshotId")||p.ContainsKey("manifestHash")&&row.ManifestHash!=Text(p,"manifestHash"))throw new IOException("快照配置已变化，请重新读取。");return row;}
 object FrozenRead(string action,Dictionary<string,object> p){ValidateFrozenConfigurationPayload(action,p);if(action=="frozenConfigurationRead")return FrozenView(CurrentFrozen(p,true));if(action=="frozenConfigurationReadCancel"){lock(gate)foreach(var reader in frozenReaderIds.Where(pair=>pair.Value==Text(p,"readId")))reader.Key.Cancel();return Message("已取消此次快照来源读取。");}if(action=="frozenConfigurationCancel"){lock(gate)foreach(var reader in frozenReaders)reader.Cancel();Cancel();return Message("已请求取消此快照操作。");}var row=CurrentFrozen(p,true);using(var source=new CancellationTokenSource()){lock(gate){if(disposed)throw new ObjectDisposedException("ModernController");frozenReaders.Add(source);frozenReaderIds[source]=p.ContainsKey("readId")?Text(p,"readId"):"";}try{return new{snapshotId=row.Id,manifestHash=row.ManifestHash,sources=FrozenConfigurationEditor.Sources(engine,source.Token,progress=>{if(Event!=null)Event("frozenConfigurationProgress",new{snapshotId=row.Id,manifestHash=row.ManifestHash,readId=p.ContainsKey("readId")?Text(p,"readId"):"",progress});})};}finally{lock(gate){frozenReaders.Remove(source);frozenReaderIds.Remove(source);}}}}
 object FrozenSave(string action,Dictionary<string,object> p){ValidateFrozenConfigurationPayload(action,p);var before=CurrentFrozen(p);var result=action=="frozenConfigurationRecover"?FrozenConfigurationEditor.Recover(engine,before.ManifestHash):action=="frozenConfigurationUninstall"?FrozenConfigurationEditor.Uninstall(engine,before.ManifestHash,FrozenIds(p["componentIds"]),cancel.Token,FrozenReport):action=="frozenConfigurationApprove"?FrozenConfigurationEditor.Approve(engine,before.ManifestHash,Text(p,"approvalToken"),(bool)p["decision"],cancel.Token,FrozenReport):FrozenConfigurationEditor.SavePrepared(engine,before.ManifestHash,FrozenIds(p["ordinaryIds"]),FrozenIds(p["componentIds"]),FrozenIds(p["sourceTokens"],true),cancel.Token,FrozenReport,FrozenDownloadDependency);engine.FrozenEnvironment=result;return new{changed=before.ManifestHash!=result.ManifestHash,committed=true,message=result.CleanupWarnings.Length==0?"快照配置已保存。":"快照配置已保存，部分旧副本等待清理。",configuration=FrozenView(result)};}
 object FrozenApprovalList(){var row=configurationReadOnly?engine.FrozenEnvironment:SaveEnvironments.FindOwned(engine.Data,engine.Game,engine.User);return new{supported=true,stamp=row.ManifestHash,jars=(row.JavaRules??new FrozenJavaRule[0]).Select(r=>new{id=r.ModId,name=r.ModId,sha256=r.Hash,approvalToken=FrozenJavaPolicy.Token(r),decision=r.Approved,warning=""}).ToArray(),warnings=row.CleanupWarnings};}
 object FrozenApprovalSave(Dictionary<string,object> p){object decision;if(!p.TryGetValue("decision",out decision)||!(decision is bool))throw new IOException("请明确允许或拒绝此文件。");var row=engine.FrozenEnvironment;string token=Text(p,"hash");var matches=(row.JavaRules??new FrozenJavaRule[0]).Where(r=>FrozenJavaPolicy.Token(r)==token||r.Hash==token).ToArray();if(matches.Length!=1)throw new IOException("请选择此快照中明确的 Java 文件。");return FrozenSave("frozenConfigurationApprove",new Dictionary<string,object>{{"snapshotId",row.Id},{"manifestHash",Text(p,"stamp")},{"approvalToken",FrozenJavaPolicy.Token(matches[0])},{"decision",decision}});}
 string FrozenComponentsAction(string key,string operation,Dictionary<string,object> p){
  if(key=="all")throw new IOException("请在启动配置编辑中逐项选择组件。");if(!new[]{"install","uninstall","update"}.Contains(operation))throw new IOException("未知组件操作。");var row=engine.FrozenEnvironment;string id=OwnedComponentId(key);var components=(FrozenConfigurationEditor.Components(row)).ToList();var tokens=new List<string>();
  if(operation=="uninstall"){Confirm(p);components.Remove(id);}else{if(!components.Contains(id))components.Add(id);if(!row.ModRoots.Any(r=>r.ModIds.Contains(id))){var matches=FrozenConfigurationEditor.Sources(engine,cancel.Token,FrozenReport).Where(s=>s.id==id).ToArray();if(matches.Length!=1)throw new IOException(id+"：请在启动配置编辑中选择明确来源后复制。");tokens.Add(matches[0].token);}else if(operation=="update")return "快照保留已复制的组件版本；如需当前来源，请在配置编辑中明确替换。";}
